  struct Traits;
  enum FlatBuffersVTableOffset FLATBUFFERS_VTABLE_UNDERLYING_TYPE {
    VT_EPOCH = 4,
    VT_ENTITY_HANDLES = 6,
    VT_OUTPUT_OFFSET = 8,
    VT_MAX_COUNT = 10,
    VT_TARGET_FRAME = 12
  };
  /// Target epoch as a Julian date (TIME_SYSTEM is configured on the host).
  double EPOCH() const {
    return GetField<double>(VT_EPOCH, 0.0);
  }
  /// Entity handles to propagate (empty = all initialized entities).
  const ::flatbuffers::Vector<uint32_t> *ENTITY_HANDLES() const {
    return GetPointer<const ::flatbuffers::Vector<uint32_t> *>(VT_ENTITY_HANDLES);
  }
  /// Output buffer offset in the arena where the StateVector stream begins.
  uint32_t OUTPUT_OFFSET() const {
    return GetField<uint32_t>(VT_OUTPUT_OFFSET, 0);
  }
  /// Maximum entities to process in this call (0 = unbounded).
  uint32_t MAX_COUNT() const {
    return GetField<uint32_t>(VT_MAX_COUNT, 0);
  }
  /// Target reference frame for the output state stream. Matches enum
  /// values in SDS `RFM`. If zero, the propagator chooses its native frame.
  const ::flatbuffers::String *TARGET_FRAME() const {
    return GetPointer<const ::flatbuffers::String *>(VT_TARGET_FRAME);
  }
  template <bool B = false>
  bool Verify(::flatbuffers::VerifierTemplate<B> &verifier) const {
    return VerifyTableStart(verifier) &&
           VerifyField<double>(verifier, VT_EPOCH, 8) &&
           VerifyOffset(verifier, VT_ENTITY_HANDLES) &&
           verifier.VerifyVector(ENTITY_HANDLES()) &&
           VerifyField<uint32_t>(verifier, VT_OUTPUT_OFFSET, 4) &&
           VerifyField<uint32_t>(verifier, VT_MAX_COUNT, 4) &&
           VerifyOffset(verifier, VT_TARGET_FRAME) &&
           verifier.VerifyString(TARGET_FRAME()) &&
           verifier.EndTable();
  }
  PRWBatchRequestT *UnPack(const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
  void UnPackTo(PRWBatchRequestT *_o, const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
